.sb-search-input-tag{align-items:center;display:inline-flex;background-color:#f0f0f0;border:1px solid rgba(60,60,60,.26);border-radius:4px;line-height:1.4;margin:4px 2px 0 2px;padding:0 .25em;z-index:0}.sb-search-input-tag.is-selectable{cursor:pointer}.sb-search-input-tag.disabled{background-color:#f8f8f8;color:rgba(60,60,60,.5);cursor:not-allowed}.sb-search-input-tag.disabled .icon path{stroke:rgba(60,60,60,.5);fill:rgba(60,60,60,.5)}.sb-search-input-tag .icon{display:inline-block;background-size:contain;height:1em;background-repeat:no-repeat;width:1em;margin:0 .25em 0 0}.sb-search-input-tag .descendants{font-size:.8em;padding:.2em .2em 0 .2em}.sb-search-input-tag .search-more{margin:0 .2em 0 .5em}.sb-search-input-tag .cross-refs{margin:0 .25em}.sb-search-input-tag button.vs__deselect{color:#3c3c3c}