.kw-wrapper{position:relative;margin-bottom:.25rem;margin-right:.25rem}.kw-wrapper.mini{margin-bottom:.125rem;margin-top:.125rem;margin-left:0;margin-right:.125em}.kw-wrapper.mini .icon{height:.7rem;width:.7rem;margin-right:.05rem}.kw-wrapper.mini .sb-keyword{font-size:.7em;padding:.125rem .25rem}.kw-wrapper>.sb-keyword{border:none;background-color:#6c757d;cursor:pointer}.kw-wrapper>.sb-keyword:hover{background-color:rgb(37.7177480434%,40.8608937137%,43.6548009762%)}.kw-wrapper>.sb-keyword:hover .sb-progress-bar{background-color:hsl(152.1818181818,68.75%,26.3725490196%)}.kw-wrapper>.sb-keyword .sb-progress-bar{position:absolute;left:0;top:0;height:100%;border-radius:.2rem;background-color:#198754}.kw-wrapper>.sb-keyword .sb-progress-bar.isDragging{background-color:#fd7e14}.kw-wrapper>.sb-keyword.highlighted .sb-progress-bar{background-color:#0dcaf0}.kw-wrapper>.sb-keyword .text{color:#fff;position:relative;text-shadow:.05em .05em .2em rgb(37.7177480434%,40.8608937137%,43.6548009762%)}.kw-wrapper>.sb-keyword .icon{position:relative;height:1rem;margin-right:.1rem;top:-0.1rem}.kw-wrapper>.sb-keyword .icon path{fill:#000;stroke:#000}.kw-wrapper>.sb-keyword .delete{position:relative;color:#f5f5f5;padding-left:.25em;font-weight:bold;cursor:pointer}.kw-wrapper>.sb-keyword .delete:hover{color:#000}