.materialListingItem{min-height:8rem;color:inherit;text-decoration:inherit}.materialListingItem:hover{color:inherit;text-decoration:inherit}.materialListingItem .preview{min-height:100%;position:relative;display:flex;flex:5;justify-content:center;border-bottom-left-radius:.25rem;border-top-left-radius:.25rem;align-items:center;overflow:hidden;cursor:pointer}.materialListingItem .preview .is-bot-corner{position:absolute;width:3em;height:3em;top:0;left:0;background:linear-gradient(to bottom right, rgba(74, 82, 90, 0.85) 50%, rgba(0, 0, 0, 0) 50%) no-repeat}.materialListingItem .preview .is-bot-corner .from-bot-icon{height:1em;width:1em;margin:.25em}.materialListingItem .preview .is-bot-corner .from-bot-icon path{fill:#fff}.materialListingItem .preview:not(.imageDisplayed){background-color:#868e96}.materialListingItem .preview.imageDisplayed{border-right:var(--bs-border-color-translucent) 1px solid}.materialListingItem .preview .image{position:absolute;object-fit:cover;width:100%;height:100%;transition:all .6s ease;-webkit-filter:brightness(1)}.materialListingItem .preview:hover .image{-webkit-transform:scale(1.3);-webkit-filter:brightness(0.5)}.materialListingItem .preview .text{height:100%;color:#dee2e6;font-size:1.25rem;display:flex;flex-direction:column;align-items:center;justify-content:center}.materialListingItem .preview .text .spinner-border{font-size:.5em;width:2em;height:2em}.materialListingItem .preview .playIcon{width:3em;height:3em;z-index:1;fill:#dee2e6}.materialListingItem .card-body{flex:20;cursor:pointer}.materialListingItem .card-body:not(.showMore) .card-text{max-height:3rem;line-height:1.5rem;overflow:hidden;text-overflow:ellipsis;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}.materialListingItem .card-body .tags{padding-bottom:.25em}.materialListingItem .more{align-items:center;display:flex;justify-content:center;min-height:100%;flex:1;min-width:1.5em;max-width:2em;background-color:#868e96;color:#dee2e6;cursor:pointer;border-bottom-right-radius:.25rem;border-top-right-radius:.25rem}.materialListingItem .more .arrow.down{transition:all .5s ease;transform:rotate(-90deg)}.materialListingItem .more .arrow.left{transition:all .5s ease;transform:rotate(0deg)}