.public-material-download{cursor:pointer}.public-material-download.showButton{display:inline-block;font-weight:400;text-align:center;vertical-align:middle;user-select:none;background-color:rgba(0,0,0,0);border:1px solid #6c757d;padding:.25em .35em 0 .5em;font-size:1em;line-height:1em;border-radius:.25rem;transition:color .15s ease-in-out,background-color .15s ease-in-out,border-color .15s ease-in-out,box-shadow .15s ease-in-out;color:#6c757d}.public-material-download.showButton:hover{color:#fff;background-color:#6c757d;text-decoration:none}.public-material-download.showButton:hover .icon{fill:#fff}.public-material-download .icon{width:1.5em;height:1.5em;fill:#6c757d;transition:color .15s ease-in-out,background-color .15s ease-in-out,border-color .15s ease-in-out,box-shadow .15s ease-in-out;top:-3px;position:relative}.public-material-download .showNormal{display:inline-block}.public-material-download .showHovered{display:none;top:0}.public-material-download:hover .showNormal{display:none}.public-material-download:hover .showHovered{display:inline-block}.public-material-download .text{padding-left:.25em}