.selected-tag{display:inline-block;position:relative;background-color:#dee2e6;border:1px solid rgba(60,60,60,.26);border-radius:4px;color:#333;line-height:1.4;margin:.25em .25em 0 0;padding:0 .25em}.selected-tag.draggable{cursor:pointer}.selected-tag.draggable .text{-webkit-touch-callout:none;-webkit-user-select:none;-khtml-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none}.selected-tag:hover{background-color:hsl(210,13.7931034483%,83.6274509804%);color:hsl(0,0%,15%)}.selected-tag:hover .selected-relevance{background-color:hsl(152.1818181818,68.75%,26.3725490196%)}.selected-tag .selected-relevance{position:absolute;left:0;top:0;height:100%;background-color:#198754}.selected-tag .selected-relevance.isDragging{background-color:#fd7e14}.selected-tag .text{display:inline;position:relative;user-select:none}