.resourceUploader .v-transmit__upload-area{width:100%;border-radius:.3rem;border:1px dashed #adb5bd;background-color:#e9ecef;min-height:5rem;display:flex}@media(min-height: 1000px){.resourceUploader .v-transmit__upload-area{min-height:300px}}.resourceUploader .v-transmit__upload-area--is-dragging{background:#e1f5fe linear-gradient(-45deg, #fafafa 25%, transparent 25%, transparent 50%, #fafafa 50%, #fafafa 75%, transparent 75%, transparent);background-size:40px 40px}.resourceUploader .errorStatusCode{font-weight:bold}