.liveEditor,.livePreview{display:inline-block;vertical-align:top;left:0;height:100%;width:100%;overflow-y:scroll}.liveEditorWrapper{background-color:#f6f6f6;border:1px solid #f6f6f6;border-right:1px solid #ccc;position:relative}.liveEditorWrapper .liveEditor{border:none;resize:none;outline:none;font-size:14px;font-family:"Monaco",courier,monospace;padding:0;background-color:rgba(0,0,0,0)}.liveEditorWrapper.savingNeccessary{border-color:#dc3545}.livePreviewWrapper{height:80vh;overflow-y:scroll}