.pdfDetailWrapper{margin:0}.pdfDetailWrapper .imageContainer .oneImagePage,.pdfDetailWrapper .imageContainer .moreImages{background-color:var(--bs-body-bg);cursor:pointer;border:1px solid #dee2e6;border-radius:var(--bs-border-radius)}.pdfDetailWrapper .imageContainer .oneImagePage .title,.pdfDetailWrapper .imageContainer .moreImages .title{font-size:.75em}.pdfDetailWrapper .imageContainer .oneImagePage .moreDots,.pdfDetailWrapper .imageContainer .moreImages .moreDots{font-size:5em;line-height:1em;color:gray}.pdfDetailWrapper .imageContainer .oneImagePage.moreImages,.pdfDetailWrapper .imageContainer .moreImages.moreImages{cursor:default;text-align:center;height:100%;background-color:var(--bs-body-bg)}